import {loyaltyRoster,membershipPending} from './loyalty-roster.js';
import {collection,query,where,getDocs,getDocFromServer,doc,orderBy,limit,onSnapshot} from 'https://www.gstatic.com/firebasejs/13.0.0/firebase-firestore.js';
import {recordLoyaltyEvent} from './loyalty-store.js';
import {rewardSummary} from './loyalty-policy.js';
import {t,language,localizeValidation} from './i18n.js';
import {bangkokToday} from './booking-validation.js';
export function setupLoyaltyAdmin(db,getUser){
 const $=s=>document.querySelector(s);let memberId=null,requestId=crypto.randomUUID(),busy=false,generation=0,generatedReference='';
 function autoReference(force=false){
  const field=$('#loyalty-reference');if(!force&&field.value.trim()&&field.value!==generatedReference)return;
  requestId=crypto.randomUUID();const prefix={visit:'VISIT',discount:'DISCOUNT',gift:'GIFT'}[$('#loyalty-action').value]||'VISIT';
  generatedReference=prefix+'-'+($('#loyalty-date').value||bangkokToday()).replaceAll('-','')+'-'+requestId.toUpperCase();field.value=generatedReference;
 }
 const message=text=>{$('#loyalty-message').textContent=t(text);$('#loyalty-message').hidden=!text};
 let rosterStops=[],rosterInvites=[],rosterMembers=[],rosterReady=0,rosterGeneration=0;
 const rosterMessage=text=>{$('#club-clients-message').textContent=t(text)};
 function stopRoster(){rosterGeneration++;for(const stop of rosterStops)stop();rosterStops=[];rosterInvites=[];rosterMembers=[];rosterReady=0;$('#club-client-list').replaceChildren()}
 function renderRoster(){
  if(rosterReady!==3)return;const search=$('#club-client-search').value.trim().toLowerCase();const all=loyaltyRoster(rosterInvites,rosterMembers),rows=all.filter(row=>(row.name+' '+row.email).toLowerCase().includes(search));const list=document.createDocumentFragment();
  const labels={sent:'Sent · not accepted yet',accepted:'Accepted · awaiting approval',active:'Accepted · active member',deliveryPending:'Email delivery pending'};
  const date=value=>value?.toDate?new Intl.DateTimeFormat(language==='th'?'th-TH-u-ca-gregory':'en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(value.toDate()):'—';
  for(const row of rows){const card=document.createElement('article');card.className='club-client-row';const info=document.createElement('div'),name=document.createElement('h3'),email=document.createElement('p'),badge=document.createElement('span'),dates=document.createElement('p');name.textContent=row.name;email.textContent=row.email;badge.className='status '+row.status;badge.textContent=t(labels[row.status]);dates.className='club-client-date';dates.textContent=[row.invitation?.lastSentAt?t('Invitation sent: {date}',{date:date(row.invitation.lastSentAt)}):!row.invitation?t('Earlier registration · invitation history unavailable'):t('Delivery not confirmed'),row.member?t('Rules accepted: {date}',{date:date(row.member.createdAt)}):''].filter(Boolean).join(' · ');info.append(name,email,badge,dates);card.append(info);
   if(row.member){const open=document.createElement('button');open.type='button';open.className=row.status==='accepted'?'gold-button':'outline-button';open.textContent=t(row.status==='accepted'?'Open & activate ↗':'Open card / Add stamp ↗');open.addEventListener('click',async()=>{if(busy)return;$('#loyalty-email').value=row.email;try{await lookup(row.email);$('#loyalty-section').scrollIntoView({behavior:'smooth'})}catch{message('Could not load membership. Please try again.')}});card.append(open)}else{const waiting=document.createElement('span');waiting.className='fine-print';waiting.textContent=t('Waiting for client acceptance');card.append(waiting)}list.append(card)
  }$('#club-client-list').replaceChildren(list);rosterMessage(rows.length?'':'No matching invitations or members.');
 }
 function startRoster(){stopRoster();const user=getUser();if(!user)return;const current=rosterGeneration;rosterMessage('Loading invitations and members…');for(const [name,bit] of [['loyaltyInvitations',1],['loyaltyMembers',2]]){rosterStops.push(onSnapshot(collection(db,name),snapshot=>{if(current!==rosterGeneration||getUser()?.uid!==user.uid)return;const rows=snapshot.docs.map(doc=>({id:doc.id,...doc.data()}));if(bit===1)rosterInvites=rows;else rosterMembers=rows;rosterReady|=bit;renderRoster()},()=>{if(current!==rosterGeneration)return;rosterReady=0;$('#club-client-list').replaceChildren();rosterMessage('Could not load invitations and members. Please refresh the list.')}))}}
 $('#view-club-clients').addEventListener('click',()=>{$('#club-clients').scrollIntoView({behavior:'smooth'});$('#club-client-search').focus({preventScroll:true})});
 $('#refresh-club-clients').addEventListener('click',startRoster);$('#club-client-search').addEventListener('input',renderRoster);
 async function approveAndNotify(){const uid=memberId,user=getUser(),current=generation;if(busy||!uid||!user)return;busy=true;$('#activate-member').disabled=true;$('#retry-activation-email').disabled=true;try{const response=await fetch('/api/loyalty-activation',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await user.getIdToken()},body:JSON.stringify({memberId:uid})});const result=await response.json();if(current!==generation||getUser()?.uid!==user.uid)return;if(!response.ok||!result.active)throw Error('Could not confirm activation. Refresh the member and try again.');await display();message(result.notification==='sent'?'Membership activated and confirmation email sent.':result.notification==='expired'?'Membership is active. This approval is too old to resend safely. Contact the client directly.':result.notification==='not_applicable'?'Membership is already active. No new approval was created.':'Membership is active, but the confirmation email could not be confirmed. Use Retry approval email.')}catch(error){if(current===generation)message(error.message||'Could not activate membership. Please try again.')}finally{busy=false;$('#activate-member').disabled=false;$('#retry-activation-email').disabled=false}}
 $('#activate-member').addEventListener('click',approveAndNotify);$('#retry-activation-email').addEventListener('click',approveAndNotify);

 async function notify(eventId,uid){const user=getUser();if(!user)return;const response=await fetch('/api/loyalty-notification',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await user.getIdToken()},body:JSON.stringify({memberId:uid,eventId})});const result=await response.json();if(!response.ok||result.notification!=='sent')throw Error('Saved, but the email could not be sent. Retry from the activity list.');}
 async function display(){
  const uid=memberId,user=getUser(),current=generation;if(!uid||!user)return;
  const snapshot=await getDocFromServer(doc(db,'loyaltyMembers',uid));if(current!==generation||getUser()?.uid!==user.uid)return;if(!snapshot.exists())throw Error('Ask the client to join Beauty Club first.');
  const data=snapshot.data(),s=rewardSummary(data);$('#loyalty-member').textContent=`${data.name} · ${data.email}`;$('#loyalty-totals').textContent=t('{visits} stamps · {discounts} discounts · {gifts} gifts available',{visits:s.stamps,discounts:s.discounts,gifts:s.gifts});$('#loyalty-actions').hidden=false;$('#loyalty-approval').hidden=!membershipPending(data);$('#loyalty-form').hidden=membershipPending(data);$('#activation-email-retry').hidden=membershipPending(data)||!data.approvedAt;
  const snapshotEvents=await getDocs(query(collection(db,'loyaltyMembers',uid,'events'),orderBy('createdAt','desc'),limit(20)));if(current!==generation)return;
  const list=document.createDocumentFragment();for(const item of snapshotEvents.docs){const e=item.data(),li=document.createElement('li');li.textContent=`${e.date} · ${t(e.type==='visit'?'Visit stamp added':e.type==='discount'?'10% reward used':'Complimentary treatment used')} · ${e.reference} `;const retry=document.createElement('button');retry.type='button';retry.className='text-button';retry.textContent=t('Retry progress email ↗');retry.addEventListener('click',async()=>{if(busy)return;retry.disabled=true;try{await notify(item.id,uid);message('Progress email sent.')}catch(error){message(error.message)}finally{retry.disabled=false}});li.append(retry);list.append(li)}$('#loyalty-history').replaceChildren(list);
 }
 async function lookup(email,bookingId=''){
  const user=getUser();if(!user)return;const current=++generation;memberId=null;$('#loyalty-actions').hidden=true;message('');$('#loyalty-form').reset();$('#loyalty-date').max=bangkokToday();$('#loyalty-date').value=bangkokToday();$('#loyalty-booking').value=bookingId;
  const results=await getDocs(query(collection(db,'loyaltyMembers'),where('email','==',email.trim().toLowerCase()),limit(2)));if(current!==generation||getUser()?.uid!==user.uid)return;
  if(results.size!==1){message('Ask the client to join Beauty Club first.');return}memberId=results.docs[0].id;autoReference(true);await display();
 }
 let inviting=false,inviteGeneration=0;
 const inviteMessage=text=>{$('#invite-message').textContent=t(text);$('#invite-message').hidden=!text};
 $('#invite-language').value=language;
 $('#invite-client').addEventListener('click',()=>{$('#invite-panel').hidden=false;$('#invite-panel').scrollIntoView({behavior:'smooth'});$('#invite-name').focus({preventScroll:true})});
 $('#invite-close').addEventListener('click',()=>{$('#invite-panel').hidden=true;$('#invite-client').focus()});
 $('#invite-form').addEventListener('submit',async e=>{e.preventDefault();const user=getUser(),current=inviteGeneration;if(inviting||!user)return;inviting=true;$('#invite-send').disabled=true;inviteMessage('Sending invitation…');const body={name:$('#invite-name').value.trim(),email:$('#invite-email').value.trim(),language:$('#invite-language').value};
  try{const response=await fetch('/api/loyalty-invitation',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await user.getIdToken()},body:JSON.stringify(body)});const result=await response.json();if(current!==inviteGeneration||getUser()?.uid!==user.uid)return;if(!response.ok||result.notification!=='sent')throw Error();inviteMessage('Invitation sent. Acceptance and activation will appear in Invitations & members.')}catch{if(current===inviteGeneration)inviteMessage('Invitation could not be confirmed. Check the address and retry; duplicate invitations are prevented for a short time.')}finally{inviting=false;$('#invite-send').disabled=false}
 });
 localizeValidation($('#invite-form'));
 $('#add-client-stamp').addEventListener('click',()=>{$('#loyalty-action').value='visit';autoReference(true);$('#loyalty-section').scrollIntoView({behavior:'smooth'});$('#loyalty-email').focus({preventScroll:true})});
 $('#loyalty-lookup').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;try{await lookup($('#loyalty-email').value)}catch{message('Could not load membership. Please try again.')}});
 for(const id of ['#loyalty-date','#loyalty-action'])$(id).addEventListener('change',()=>autoReference());
 $('#loyalty-new-visit').addEventListener('click',()=>{if(busy)return;$('#loyalty-form').reset();$('#loyalty-date').value=bangkokToday();autoReference(true);message('');$('#loyalty-paid').focus()});
 $('#loyalty-form').addEventListener('input',()=>{requestId=crypto.randomUUID()});
 $('#loyalty-form').addEventListener('submit',async e=>{e.preventDefault();const user=getUser(),uid=memberId;if(busy||!uid||!user)return;busy=true;$('#loyalty-save').disabled=true;message('');
  try{const result=await recordLoyaltyEvent(db,user,uid,{type:$('#loyalty-action').value,date:$('#loyalty-date').value,reference:$('#loyalty-reference').value,bookingId:$('#loyalty-booking').value,note:$('#loyalty-note').value,completedPaid:$('#loyalty-paid').checked,requestId});message(result.duplicate?'This visit has already earned a stamp.':'Beauty Club updated.');await display();try{await notify(result.eventId,uid);message('Beauty Club updated and progress email sent.')}catch(error){message(error.message)}}
  catch(error){message(error.code==='permission-denied'?'You do not have permission to change this card.':error.message||'Could not save. Check your connection and try again.')}
  finally{busy=false;$('#loyalty-save').disabled=false}
 });
 $('#loyalty-date').value=bangkokToday();$('#loyalty-date').max=bangkokToday();autoReference(true);for(const id of ['#loyalty-form','#loyalty-lookup'])localizeValidation($(id));
 return {start:startRoster,reset(){stopRoster();$('#club-client-search').value='';rosterMessage('');inviteGeneration++;$('#invite-panel').hidden=true;$('#invite-form').reset();$('#invite-language').value=language;inviteMessage('');generation++;memberId=null;$('#loyalty-actions').hidden=true;$('#loyalty-history').replaceChildren();$('#loyalty-lookup').reset();$('#loyalty-form').reset();$('#loyalty-member').textContent='';$('#loyalty-totals').textContent='';message('')},async open(booking){$('#loyalty-email').value=booking.email||'';$('#request-dialog').close();$('#loyalty-section').scrollIntoView({behavior:'smooth'});try{await lookup(booking.email,booking.id);$('#loyalty-date').value=booking.confirmedDate||bangkokToday();autoReference()}catch{message('Could not load membership. Please try again.')}}};
}
